SELECT a, sum(b) OVER w FROM t WHERE x = 1 WINDOW w AS (ORDER BY a);
SELECT a, sum(b) OVER w FROM t PREWHERE p = 1 WHERE x = 1 GROUP BY a, b HAVING a > 1 WINDOW w AS (PARTITION BY a ORDER BY b) ORDER BY a LIMIT 10;
SELECT a, count() OVER w FROM t GROUP BY a WITH TOTALS HAVING count() > 1 WINDOW w AS (ORDER BY a);
